  "How Far Will You Go?": "Как далеко поедете?",
  "Looking for rides…": "Ищем поездки…",
  "Create a Public Ride": "Создать публичную поездку",
  "The map opens on your location or the state you pick.": "Карта откроется на вашем местоположении или в выбранном штате.",
  "Save the people you ride with. When you create a ride, invite the whole group in one tap.": "Сохраните тех, с кем катаетесь. Создавая поездку, приглашайте всю группу одним касанием.",
  "Your Groups": "Ваши группы",
