  "Their Upcoming Rides": "Их ближайшие поездки",
  "Tap Follow on a ride page to hear when that leader posts a new public ride.": "Нажмите «Подписаться» на странице поездки, чтобы узнавать, когда этот ведущий публикует новую публичную поездку.",
  "No Groups Yet": "Групп пока нет",
  "Make one for the friends you ride with most weekends. Add people you’ve ridden with, or send the group link to anyone else.": "Создайте группу для друзей, с которыми катаетесь почти каждые выходные. Добавьте тех, с кем уже ездили, или отправьте ссылку на группу остальным.",
  "Almost Ready": "Почти готово",
  "Add the backend keys to app/.env (see .env.example), then restart the app.": "Добавьте ключи бэкенда в app/.env (см. .env.example), затем перезапустите приложение.",
  "Admin Dashboard": "Панель администратора",
  "Starlink": "Starlink",
  "OnMyLead Admin": "OnMyLead Admin",
  "Signing you in…": "Выполняем вход…",
  "Open OnMyLead": "Открыть OnMyLead",
  "Finish signing in inside the app, or carry on here in the browser.": "Завершите вход в приложении или продолжите здесь, в браузере.",
  "Open in the App": "Открыть в приложении",
  "Continue on the Website": "Продолжить на сайте",
  "Let’s Ride": "Поехали",
  "Your Email Is Confirmed": "Ваш email подтвержден",
  "This link opened somewhere other than where you signed up, so sign in once more with your email and password.": "Ссылка открылась не там, где вы регистрировались, поэтому войдите еще раз с email и паролем.",
  "That Link Didn’t Work": "Ссылка не сработала",
  "Back to Sign In": "Вернуться ко входу",
  "Sign in to earn badges for the rides you lead, join and finish.": "Войдите, чтобы получать значки за поездки, которые вы ведете, в которых участвуете и которые завершаете.",
  "Badges start working with the next server update.": "Значки заработают после следующего обновления сервера.",
  "Try Again": "Повторить",
  "A ride counts once it ends, for riders whose own location track covers at least half a mile. Leading, tail gunning and group rides need at least two riders with a track. Badges are earned on the server from what you really ride, so they can’t be added by hand. OnMyLead Founder and Brand Ambassador are the exceptions: OnMyLead gives them, and they don’t count toward your rank.": "Поездка засчитывается после окончания для райдеров, чей трек местоположения покрывает не меньше полумили. Ведение, роль замыкающего и групповые поездки требуют минимум двух райдеров с треком. Значки начисляются на сервере по тому, что вы реально проехали, поэтому их нельзя добавить вручную. Исключения — OnMyLead Founder и Brand Ambassador: их выдает OnMyLead, и они не влияют на ваш ранг.",
  "Your Rank": "Ваш ранг",
  "New": "Новое",
  "{what}. Riders see it beside your name.": "{what}. Райдеры видят это рядом с вашим именем.",
  "Keep Current": "Оставить текущий",
  "Saved, but your current share didn’t switch over. Open Ride Mode to restart sharing with the new setting.": "Сохранено, но текущая передача местоположения не переключилась. Откройте Режим поездки, чтобы перезапустить передачу с новой настройкой.",
  "How often this device tells your group where you are while you share your location. Fewer updates use less battery.": "Как часто это устройство сообщает группе, где вы, пока вы делитесь местоположением. Реже — значит меньше расход батареи.",
  "Your Group Sees You Less Often": "Группа видит вас реже",
  "Your dot can trail up to {heartbeatSec} seconds behind you, so you’re harder to follow and to find if you stop.": "Ваша точка может отставать от вас до {heartbeatSec} секунд, поэтому за вами труднее следовать и вас труднее найти, если вы остановились.",
  "Switch Back to Best Accuracy": "Вернуть максимальную точность",
  "This setting is for this device only. Need Help, EMERGENCY and your other taps still send right away on every setting. Other riders aren’t told which one you picked.": "Эта настройка только для этого устройства. «Нужна помощь», ТРЕВОГА и другие нажатия отправляются сразу при любой настройке. Другие райдеры не знают, что вы выбрали.",
  "Recommended": "Рекомендуется",
  "You don’t see their messages in ride chat or group chat, or get chat notifications from them. They aren’t told. Need Help and EMERGENCY alerts from a ride you’re on always come through.": "Вы не видите их сообщения в чате поездки или группы и не получаете от них уведомлений чата. Им об этом не сообщается. Сигналы «Нужна помощь» и ТРЕВОГА из поездки, в которой вы участвуете, приходят всегда.",
  "Loading…": "Загрузка…",
  "Nobody Blocked": "Никто не заблокирован",
  "To block a rider, tap them in a ride’s Going list, or long press one of their messages.": "Чтобы заблокировать райдера, нажмите на него в списке участников поездки или удерживайте одно из его сообщений.",
  "Unblock": "Разблокировать",
  "Your pictures couldn’t be opened. Allow OnMyLead to see your photos in Settings, or send the message without one.": "Не удалось открыть изображения. Разрешите OnMyLead доступ к фото в Настройках или отправьте сообщение без них.",
  "Message Sent | OnMyLead": "Сообщение отправлено | OnMyLead",
  "Message Sent": "Сообщение отправлено",
  "Thanks for writing. We’ll reply to {sentTo}, usually within a day.": "Спасибо, что написали. Мы ответим на {sentTo}, обычно в течение дня.",
  "Back to OnMyLead": "Вернуться в OnMyLead",
  "Send Another Message": "Отправить еще одно сообщение",
  "Contact Us | OnMyLead": "Связаться с нами | OnMyLead",
