  "In Map Mode, tap Record and ride, or Draw to map a custom trail. Your trails are private until you share them, and they show on every device you sign in on. A rider trail you save shows here too.": "В Режиме карты нажмите «Записать» и езжайте или «Нарисовать», чтобы нанести свою трассу. Ваши трассы приватны, пока вы ими не поделитесь, и видны на каждом устройстве, где вы вошли. Сохраненная трасса райдера тоже появится здесь.",
  "Notifications Come to the iPhone App": "Уведомления приходят в приложение для iPhone",
