  "Turn On Notifications": "Включить уведомления",
  "So you hear when someone in your group needs help, even with the phone in your pocket.": "Чтобы вы узнали, когда кому-то из группы нужна помощь, даже если телефон в кармане.",
  "These settings start working with the next server update. Until then, ride chat still pops up while the app is open.": "Эти настройки заработают после следующего обновления сервера. До тех пор чат поездки всплывает, пока приложение открыто.",
  "Help and EMERGENCY alerts are always on, even in quiet hours.": "Сигналы «Помощь» и ТРЕВОГА всегда включены, даже в тихие часы.",
  "SOS": "SOS",
  "Help and EMERGENCY": "Помощь и ТРЕВОГА",
  "When someone in your group taps Need help or EMERGENCY. Always on, even in quiet hours.": "Когда кто-то из группы нажимает «Нужна помощь» или ТРЕВОГА. Всегда включено, даже в тихие часы.",
  "Email When a Ride Is Cancelled": "Email при отмене поездки",
  "An email if a ride you joined is cancelled or removed, as well as the notification.": "Письмо, если поездку, к которой вы присоединились, отменили или удалили, в дополнение к уведомлению.",
  "Email Me Too": "И по email",
  "The same Pro Trial reminders by email.": "Те же напоминания о пробном Pro по email.",
  "Show Message Text": "Показывать текст сообщений",
  "Off keeps messages off your lock screen. You’ll see who wrote, not what.": "Выключено — сообщения не видны на экране блокировки. Вы увидите, кто написал, но не что.",
  "Ride reminder": "Напоминание о поездке",
  "A heads-up before each ride you’ve joined, with the meeting spot.": "Напоминание перед каждой поездкой, к которой вы присоединились, с местом встречи.",
  "Quiet hours": "Тихие часы",
  "Silence Overnight": "Тишина ночью",
  "From": "С",
  "Until": "До",
  "You’re Out Riding": "Вы в пути",
  "{v}. {v2} can see your name and roughly how far away you are.": "{v}. {v2} могут видеть ваше имя и примерное расстояние до вас.",
  "Everyone nearby who chose Everyone Nearby": "Все поблизости, кто выбрал «Все поблизости»",
  "Your friends and riders you know": "Ваши друзья и знакомые райдеры",
  "At {spot}": "В {spot}",
  "Turn Off": "Выключить",
  "Switch on Out Riding to see who else is out near you, like friends showing online in a game. Off until you switch it on.": "Включите «В пути», чтобы видеть, кто еще катается рядом, как друзей онлайн в игре. Выключено, пока вы не включите.",
  "Who Can See Me": "Кто меня видит",
  "Turn Off After": "Выключить через",
  "Where You’re Riding (Optional)": "Где вы катаетесь (необязательно)",
  "Shown to riders who can see you. Leave it blank to just show the distance.": "Показывается райдерам, которые вас видят. Оставьте пустым, чтобы показывать только расстояние.",
  "Windrock Park": "Windrock Park",
  "Riders see your name and roughly how far away you are, never where you are. It turns off on its own at the end you pick, or after {IDLE_HOURS} hours without opening OnMyLead.{v}": "Райдеры видят ваше имя и примерное расстояние, но никогда не где вы. Выключается само в выбранный срок или через {IDLE_HOURS} ч без открытия OnMyLead.{v}",
  "Your browser will ask for your location.": "Браузер запросит ваше местоположение.",
  "Go Out Riding": "Выйти в путь",
