  "Draw the trail on the map or import a GPX file. Riders see it in Ride Mode with everyone placed along it.": "Нарисуйте трассу на карте или импортируйте файл GPX. Райдеры видят ее в Режиме поездки, и все отмечены вдоль нее.",
