  "Map": "Карта",
  "Chat": "Чат",
  "Pick who you want to report for harassment, threats or anything else that breaks the rider rules. It goes to the OnMyLead team. They aren’t told who reported them. If anyone is in danger, call 911.": "Выберите, на кого хотите пожаловаться за домогательства, угрозы или другое нарушение правил райдеров. Жалоба уходит команде OnMyLead. Ему не сообщат, кто пожаловался. Если кто-то в опасности, звоните 911.",
  "Search": "Поиск",
  "Rider name": "Имя райдера",
  "Riders you’ve messaged, ridden with, added as friends or blocked show here. You can also report a rider from their message, a ride’s Going list or Out Riding.": "Здесь появляются райдеры, которым вы писали, с которыми ездили, добавили в друзья или заблокировали. Пожаловаться на райдера можно и из его сообщения, списка участников поездки или «В пути».",
  "Opening your reset link…": "Открываем ссылку для сброса…",
  "This Link Has Expired": "Срок действия ссылки истек",
  "Ask for a new reset link from the sign-in screen, and open it on this device.": "Запросите новую ссылку для сброса на экране входа и откройте ее на этом устройстве.",
