  "Buttons ▲": "Кнопки ▲",
  "Share Your Location with This Ride?": "Поделиться местоположением с этой поездкой?",
  "Only riders on this ride will see you. Sharing always stops when the ride ends or you leave it.": "Вас увидят только райдеры этой поездки. Передача всегда прекращается, когда поездка заканчивается или вы ее покидаете.",
  "Emergency": "Экстренная ситуация",
  "This alerts everyone on the ride with your location. It does not contact emergency services. Call 911 if anyone is hurt.": "Это оповестит всех в поездке и передаст ваше местоположение. Экстренные службы не вызываются. Звоните 911, если кто-то пострадал.",
