  "Add at My Location": "Добавить в моем местоположении",
  "Waypoints are never public. Shared ones and planned stops show only to riders on this ride.": "Точки маршрута никогда не публичны. Общие точки и запланированные остановки видны только райдерам этой поездки.",
  "Pick Public or Private at the top.": "Выберите вверху «Публичная» или «Частная».",
  "Give the ride a name.": "Дайте поездке название.",
  "Pick a meeting time.": "Выберите время встречи.",
  "Pick a day from today up to three years out.": "Выберите день от сегодня до трех лет вперед.",
  "Set the meeting point: search a place, use your location or paste coordinates like \"38.57, -109.55\".": "Укажите место встречи: найдите место, используйте свое местоположение или вставьте координаты вида \"38.57, -109.55\".",
  "Pick Mapped or Freeride under The Route.": "Выберите «По маршруту» или «Фрирайд» в разделе «Маршрут».",
  "Plan it here on the big screen. The ride, its route and its stops show up in the OnMyLead app on your iPhone as soon as you save.": "Планируйте здесь, на большом экране. Поездка, ее маршрут и остановки появятся в приложении OnMyLead на вашем iPhone сразу после сохранения.",
  "Riding {copiedFrom} Again": "Снова {copiedFrom}",
