  "Map Style": "Стиль карты",
  "Map style": "Стиль карты",
  "Public Trails and Roads": "Публичные трассы и дороги",
  "Road": "Дорога",
  "Closed": "Закрыто",
  "Closed means the Forest Service, BLM or OpenStreetMap lists it closed or private today, from their published travel plans and seasons. It is not a live gate report, so check posted signs and local orders.": "«Закрыто» означает, что Лесная служба, BLM или OpenStreetMap сегодня указывают ее закрытой или частной по опубликованным планам движения и сезонам. Это не данные о шлагбаумах в реальном времени, поэтому смотрите на знаки и местные распоряжения.",
  "Rider Trails": "Трассы райдеров",
  "Trails OnMyLead riders mapped and shared. User submitted, so check them against signs.": "Трассы, нанесенные и опубликованные райдерами OnMyLead. Добавлены пользователями, сверяйте их со знаками.",
  "Map data: {credit}": "Картографические данные: {credit}",
  "Saves satellite, topo and trails around this ride's route for riding with no signal": "Сохраняет спутник, топокарту и трассы вокруг маршрута этой поездки для езды без связи",
  "Download This Ride’s Map": "Скачать карту этой поездки",
  "Mapped by riders on OpenStreetMap. Parks and private land need permission or a pass.": "Нанесено райдерами в OpenStreetMap. В парках и на частной земле нужно разрешение или пропуск.",
  "From {attribution}. Check posted signs and closures before you ride.": "Источник: {attribution}. Проверяйте знаки и закрытия перед поездкой.",
  "Not Rated": "Без оценок",
  "No trails yet. Record or draw one in Map Mode, or save a rider trail, and it shows here.": "Трасс пока нет. Запишите или нарисуйте трассу в Режиме карты или сохраните трассу райдера, и она появится здесь.",
  "Enter the width in inches, like 50.": "Введите ширину в дюймах, например 50.",
  "The narrowest gap you measured or a posted limit, in inches.": "Самый узкий проход, который вы измерили, или указанное ограничение, в дюймах.",
  "Width limit in inches": "Ограничение ширины в дюймах",
