  "Start date should look like 2026-10-12.": "Дата начала должна выглядеть так: 2026-10-12.",
  "End date should look like 2026-10-14.": "Дата окончания должна выглядеть так: 2026-10-14.",
  "The trip ends before it starts.": "Поездка заканчивается раньше, чем начинается.",
  "Trip Name": "Название поездки",
