  "the App Store": "App Store",
  "Please Update OnMyLead": "Пожалуйста, обновите OnMyLead",
  "This version ({v}) has a problem that's fixed in version {minimum} or newer, which is in {store} now. Updating keeps all your rides, groups and settings.": "В этой версии ({v}) есть проблема, исправленная в версии {minimum} или новее, которая уже доступна в {store}. При обновлении все ваши поездки, группы и настройки сохранятся.",
  "Update Now": "Обновить сейчас",
  "On a ride with no signal? Tap Not Now. Ride Mode and Help and SOS keep working, and we'll ask again next time you open the app.": "В поездке без связи? Нажмите «Не сейчас». Режим поездки и «Помощь и SOS» продолжат работать, а мы спросим снова при следующем открытии приложения.",
  "Pick Vehicle or SXS/UTV first.": "Сначала выберите «Автомобиль» или «SXS/UTV».",
  "Year should look like 2022.": "Год должен выглядеть так: 2022.",
  "Give it a nickname or a make and model.": "Укажите прозвище или марку и модель.",
  "What Are You Adding?": "Что добавляете?",
  "Photo of your machine": "Фото вашей техники",
  "Add a photo of your machine.": "Добавьте фото вашей техники.",
