  "Tank (gal)": "Бак (гал)",
  "Extra Fuel (gal)": "Доп. топливо (гал)",
  "Miles per Gallon": "Миль на галлон",
  "Your real-world trail mpg, not the sticker.": "Ваш реальный расход на трассе, а не паспортный.",
  "About {v} miles on {totalGallons} gallons. Turn around by {v2} miles out.": "Около {v} миль на {totalGallons} галлонах. Разворачивайтесь на {v2} миле.",
  "Trail Fit": "Габариты для трассы",
  "Width (Inches)": "Ширина (дюймы)",
  "Widest point, tire to tire. Trails with a width limit show whether it fits.": "Самое широкое место, от шины до шины. Трассы с ограничением ширины покажут, пройдет ли техника.",
  "That time looks off. Try \"12:30 pm\".": "Время выглядит неверно. Попробуйте \"12:30 pm\".",
  "Symbol": "Значок",
  "Lunch at the Overlook": "Обед на смотровой",
