  "{hh} h {mm} min": "{hh} ч {mm} мин",
  "Enter the dish watts and hours per day to see your budget.": "Введите мощность тарелки и часы в день, чтобы увидеть баланс.",
  "The dish needs about {v} a day. Add your battery or solar to see how long it lasts.": "Тарелке нужно около {v} в день. Добавьте батарею или солнечные панели, чтобы увидеть, на сколько хватит.",
  "Solar keeps up: about {v} to spare each day at {hoursPerDay} h a day.": "Солнце справляется: около {v} в запасе каждый день при {hoursPerDay} ч в день.",
  "Solar covers {v}% of the dish's daily use. Add a battery to store it.": "Солнце покрывает {v}% суточного расхода тарелки. Добавьте батарею, чтобы накапливать энергию.",
  "At {hoursPerDay} h a day the battery runs out on day one, after about {v} of use.": "При {hoursPerDay} ч в день батарея сядет в первый же день, примерно через {v} работы.",
