  "In {days} Days": "Через {days} дн.",
  "Keep it under {RIDE_MESSAGE_MAX} characters ({length} now).": "Не больше {RIDE_MESSAGE_MAX} символов (сейчас {length}).",
  "Give the ride to {name}?": "Передать поездку {name}?",
  "{name} becomes the organizer and leader. You stay on the ride as a rider and can't undo this yourself.": "{name} станет организатором и ведущим. Вы останетесь в поездке как райдер и не сможете отменить это сами.",
  "Hand the lead to {name}?": "Передать ведение {name}?",
  "{name} leads from here, and messages to the leader go to them. You stay on the ride as a rider.": "Дальше ведет {name}, и сообщения ведущему будут приходить ему. Вы останетесь в поездке как райдер.",
  "Handing off the ride and picking a tail gunner aren’t switched on yet.": "Передача поездки и выбор замыкающего еще не включены.",
  "They need to join the ride first.": "Сначала он должен присоединиться к поездке.",
