  "Earn your first badge level to get on the board.": "Получите первый уровень значка, чтобы попасть в рейтинг.",
  "Everywhere": "Везде",
  "Leaderboard. See where you rank in your state, your country and everywhere": "Рейтинг. Ваше место в штате, стране и везде",
  "No country matches “{v}”.": "Нет страны, похожей на «{v}».",
  "No tilt tile, readings or tilt warnings. Crash Alert still works.": "Нет плитки наклона, показаний и предупреждений. Сигнал аварии работает.",
  "Pick the state or country you ride from to be on its leaderboard. Riders see it beside your name there, and nowhere else. It’s optional, and it never shares where you are.": "Выберите штат или страну, откуда вы катаетесь, чтобы попасть в их рейтинг. Райдеры видят это рядом с вашим именем только там. Это необязательно и никогда не показывает, где вы находитесь.",
  "Pick where you ride from to be on country and state boards.": "Выберите, откуда вы катаетесь, чтобы попасть в рейтинги стран и штатов.",
  "Place your phone where it will be mounted, with the vehicle on flat and level ground, then press {button} to calibrate it.": "Установите телефон туда, где он будет закреплён, поставьте машину на ровную площадку и нажмите {button}, чтобы откалибровать.",
  "Remove My Area": "Убрать мой регион",
  "Riders are ranked by the badge levels they earned by riding, the same count as their rank. Ties go to more Gold, then more Silver, then whoever got there first. Brand Ambassador and OnMyLead Founder don’t count. Only your name, picture, badges and the state or country you picked show here, never where you are.": "Райдеры ранжируются по уровням значков, заработанным в поездках, — тот же счёт, что и их ранг. При равенстве выше тот, у кого больше Золота, затем Серебра, затем тот, кто достиг первым. Brand Ambassador и OnMyLead Founder не считаются. Здесь видны только ваше имя, фото, значки и выбранный штат или страна, но никогда не то, где вы находитесь.",
  "Roll and pitch on this screen and in Map Mode and Ride Mode.": "Крен и тангаж на этом экране, в режиме карты и Режиме поездки.",
  "Saving 3D Terrain, {v}%": "Сохранение 3D-рельефа, {v}%",
  "Search Countries": "Поиск стран",
  "See where you rank in your state, your country and everywhere": "Ваше место в штате, стране и везде",
