  "Show Me on the Leaderboard": "Показывать меня в рейтинге",
  "Sign in to see where you rank among riders in your state, your country and everywhere.": "Войдите, чтобы увидеть своё место среди райдеров штата, страны и всех остальных.",
  "Somewhere else? Type its name.": "Другое место? Введите название.",
