  "The tilt meter is off until you calibrate it. Place your phone where it will be mounted, with the vehicle on flat and level ground, then press Calibrate.": "Измеритель наклона выключен, пока вы его не откалибруете. Установите телефон туда, где он будет закреплён, поставьте машину на ровную площадку и нажмите «Откалибровать».",
