  "Unblock {name}": "Разблокировать {name}",
  "Your browser and a short log of what the page just did go with your message, to help us fix it. Never your location or anything you typed.": "Вместе с сообщением отправляются ваш браузер и короткий журнал того, что только что делала страница, чтобы помочь нам исправить проблему. Никогда — ваше местоположение или введённый текст.",
  "Your phone model, app version and a short log of what the app just did go with your message, to help us fix it. Never your location or anything you typed.": "Вместе с сообщением отправляются модель телефона, версия приложения и короткий журнал того, что только что делало приложение, чтобы помочь нам исправить проблему. Никогда — ваше местоположение или введённый текст.",
  "We couldn’t find that event.": "Мы не нашли это событие.",
  "{title}, {v} at {location_name}. Agenda, group rides and who’s going: {link}": "{title}, {v} в {location_name}. Программа, групповые поездки и кто едет: {link}",
  "An event can have up to {v} photos. Remove one to add another.": "У события может быть до {v} фото. Удалите одно, чтобы добавить другое.",
