  "{title} | OnMyLead Events": "{title} | События OnMyLead",
  "{v} at {location_name}. Agenda, group rides and who’s going on OnMyLead.": "{v} в {location_name}. Программа, групповые поездки и кто едет — в OnMyLead.",
  "Pick a Ride Manager": "Выбрать ответственного за поездку",
  "Add a Co-Host": "Добавить соорганизатора",
  "They become a Co-Organizer of {name}: they can approve riders, set roles and run the ride. If they aren’t on it yet, they get an invite first.": "Становится соорганизатором {name}: может одобрять райдеров, назначать роли и вести поездку. Если ещё не в ней, сначала получит приглашение.",
  "Pick from your friends and the riders you’ve ridden with.": "Выберите из друзей и райдеров, с которыми вы ездили.",
