  "No Public Events Coming Up": "Предстоящих публичных событий нет",
  "Events you host, co-host or say you’re going to show up here.": "Здесь появляются события, которые вы организуете, соорганизуете или на которые собираетесь.",
  "Nothing within {v} miles yet. Widen the distance, or create one and it shows here for everyone.": "В радиусе {v} миль пока ничего нет. Расширьте расстояние или создайте событие — оно появится здесь для всех.",
  "Create one and it shows here for everyone.": "Создайте событие — оно появится здесь для всех.",
  "Couldn’t save the event.": "Не удалось сохранить событие.",
  "Shows in Events for every rider, and anyone with the link can open it.": "Отображается в Событиях для всех райдеров, и любой со ссылкой может открыть.",
  "Only people you send the link to can open it.": "Открыть могут только те, кому вы отправите ссылку.",
