  ". Swipe Left to Clear": ". Смахните влево, чтобы удалить",
  "Notifications OnMyLead sends to your phone app show up here too, for 30 days.": "Уведомления, которые OnMyLead отправляет на телефон, тоже показываются здесь 30 дней.",
  "Ride messages, rider alerts, ride changes, invites and friend requests show up here for 30 days.": "Сообщения поездки, оповещения райдеров, изменения поездки, приглашения и запросы в друзья показываются здесь 30 дней.",
  "New. ": "Новое. ",
  "Clear {title}": "Удалить {title}",
  "Send your link to a riding buddy who’s new to OnMyLead. When they finish their first ride, you both get Pro Annual for ${discounted} the first year instead of ${annual}.": "Отправьте свою ссылку товарищу, который только начинает с OnMyLead. Когда он завершит первую поездку, вы оба получите Pro на год за ${discounted} в первый год вместо ${annual}.",
  "Invites aren’t open right now. Any discount you already earned is below.": "Приглашения сейчас закрыты. Скидка, которую вы уже заработали, ниже.",
  "Copy Link": "Копировать ссылку",
  "{name} invited you, and your first ride counted.": "{name} пригласил вас, и ваша первая поездка засчитана.",
  "{name} invited you. Finish your first ride and you both get 50% off Pro Annual.": "{name} пригласил вас. Завершите первую поездку, и вы оба получите скидку 50 % на Pro на год.",
  "Your friend creates a new account with your link within {newAccountDays} days and finishes a ride that ran at least {minRideMinutes} minutes. Each rider can earn the discount once, and it can be claimed for 6 months. On iPhone and iPad it’s an App Store offer code; on Android it’s a Google Play offer. If you already pay for Pro on Google Play, your next bill moves back 6 months instead. The discount covers the first year of Pro Annual, which then renews at the regular price unless you cancel.": "Ваш друг создаёт новый аккаунт по вашей ссылке в течение {newAccountDays} дней и завершает поездку длительностью не менее {minRideMinutes} минут. Каждый райдер может получить скидку один раз, и её можно использовать в течение 6 месяцев. На iPhone и iPad это код предложения App Store; на Android — предложение Google Play. Если вы уже платите за Pro в Google Play, вместо этого ваш следующий платёж сдвигается на 6 месяцев. Скидка действует на первый год Pro на год, затем подписка продлевается по обычной цене, если вы её не отмените.",
  "Pick your {v} below.": "Выберите {v} ниже.",
  "That didn’t save. {message}": "Не сохранилось. {message}",
  "Finding Your State…": "Определяем ваш штат…",
