  "No riders from {v} on the board yet. Riders show here once they pick where they ride from and earn a badge level.": "Райдеров из {v} в таблице пока нет. Райдеры появляются здесь, когда указывают, откуда ездят, и получают уровень значка.",
  "No riders on the board yet.": "Райдеров в таблице пока нет.",
