  "   {v} Free on This Phone": "   Свободно на этом телефоне: {v}",
  "It’s removed from your Messages. {who} keeps their copy. If they message you again, it comes back.": "Удаляется из ваших Сообщений. {who} сохраняет свою копию. Если он снова напишет, переписка вернётся.",
