  "Riders rated its line inaccurate, so other riders can’t see it. It’s still saved on this phone. Re-record it and share again.": "Райдеры оценили её линию как неточную, поэтому другие райдеры её не видят. Она по-прежнему сохранена на этом телефоне. Запишите заново и поделитесь снова.",
  "Centers the map on you and follows you again": "Центрирует карту на вас и снова следует за вами",
  "Centers the map on you": "Центрирует карту на вас",
  "Free Map Mode: {mapTimeText}": "Бесплатный режим карты: {mapTimeText}",
  "{mint} are trails other riders mapped and shared.": "{mint} — это трассы, которые записали и опубликовали другие райдеры.",
