  "Recording works in the OnMyLead app on your phone or tablet. Here you can measure, plan and look at trails.": "Запись работает в приложении OnMyLead на телефоне или планшете. Здесь можно измерять, планировать и смотреть трассы.",
  "Turn on location for OnMyLead in Settings to record.": "Включите геолокацию для OnMyLead в Настройках, чтобы записывать.",
  "Ride and OnMyLead draws your line. It stays on this phone unless you share it. Keep Map Mode open: the screen stays on while recording.": "Едьте, и OnMyLead нарисует вашу линию. Она остаётся на этом телефоне, пока вы ею не поделитесь. Держите режим карты открытым: экран не гаснет во время записи.",
  "Paused": "Пауза",
