  "Mark a Spot": "Отметить место",
  "Couldn’t load the trail.": "Не удалось загрузить трассу.",
  "This trail isn’t on the public map any more.": "Этой трассы больше нет на публичной карте.",
  "It comes off the public map with its photos and ratings. Your copy stays in My Trails. Rides that used it keep their route.": "Она уходит с публичной карты вместе с фото и оценками. Ваша копия остаётся в «Мои трассы». Поездки, которые её использовали, сохраняют маршрут.",
  "It comes off the public map with its photos and ratings. Rides that used it keep their route.": "Она уходит с публичной карты вместе с фото и оценками. Поездки, которые её использовали, сохраняют маршрут.",
  "Couldn’t delete it.": "Не удалось удалить.",
  "Couldn’t save it.": "Не удалось сохранить.",
  "Map of {name}": "Карта {name}",
  "Photo of {name}": "Фото {name}",
  "Change Your Rating": "Изменить оценку",
