  "That trail isn’t on this device.": "Этой трассы нет на этом устройстве.",
  "Couldn’t save.": "Не удалось сохранить.",
  "Every OnMyLead rider will see {v}, its named spots, photos and your ride name. Riders can rate it; if several say it’s inaccurate it’s hidden from them, but it stays on your phone.": "Все райдеры OnMyLead увидят {v}, отмеченные места, фото и название вашей поездки. Райдеры могут её оценивать; если несколько сочтут её неточной, она скроется от них, но останется на вашем телефоне.",
  "Couldn’t share the trail.": "Не удалось поделиться трассой.",
