  "Several riders rated this line inaccurate, so other riders can’t see it. It’s still yours here. Record it again and share the new one.": "Несколько райдеров оценили эту линию как неточную, поэтому другие райдеры её не видят. Здесь она по-прежнему ваша. Запишите заново и поделитесь новой.",
  "+ Photo": "+ Фото",
  "Save on This Phone": "Сохранить на этом телефоне",
  "Drawn": "Нарисована",
  "Likes and Comments notifications are not switched on yet. They start working with the next server update.": "Уведомления о лайках и комментариях пока не включены. Они заработают после следующего обновления сервера.",
  "Friend Request notifications are not switched on yet. They start working with the next server update.": "Уведомления о запросах в друзья пока не включены. Они заработают после следующего обновления сервера.",
  "Direct Message notifications are not switched on yet. They start working with the next server update.": "Уведомления о личных сообщениях пока не включены. Они заработают после следующего обновления сервера.",
  "Riding Group Chat notifications are not switched on yet. They start working with the next server update.": "Уведомления чата группы пока не включены. Они заработают после следующего обновления сервера.",
  "Ride Invites and Leaders You Follow are not switched on yet. They start working with the next server update.": "Приглашения в поездки и ведущие, на которых вы подписаны, пока не включены. Они заработают после следующего обновления сервера.",
  "Account notifications are not switched on yet. They start working with the next server update.": "Уведомления об аккаунте пока не включены. Они заработают после следующего обновления сервера.",
  "Couldn’t save that. {message}": "Не удалось сохранить. {message}",
  "Open iPhone Settings": "Открыть настройки iPhone",
  "Silent for {v} hours a day. Help alerts still come through.": "Тишина {v} ч в день. Сигналы о помощи всё равно приходят.",
  "Hold everything but help alerts overnight.": "На ночь задерживать всё, кроме сигналов о помощи.",
  "Quiet from {v} until {v2}": "Тишина с {v} до {v2}",
