  "{label} half an hour later": "{label} на полчаса позже",
  "Change Out Riding": "Изменить «В пути»",
  "Going Riding?": "Едете кататься?",
  "Your friends and riders you know show up here when they switch on Out Riding too.": "Ваши друзья и знакомые райдеры появляются здесь, когда тоже включают «В пути».",
  "Anyone at the same park shows up here once they switch on Out Riding with Everyone Nearby.": "Любой в том же парке появляется здесь, когда включает «В пути» с «Все поблизости».",
  "Ridden With You": "Ездил с вами",
  "New Rider": "Новый райдер",
  "More for {display_name}": "Ещё для {display_name}",
  "Subscriptions are in the OnMyLead app. Pro you buy there works here too.": "Подписки оформляются в приложении OnMyLead. Pro, купленный там, работает и здесь.",
  "Subscriptions open in an upcoming update. Until then your plan stays as it is and nothing is charged.": "Подписки откроются в одном из следующих обновлений. До тех пор ваш план остаётся прежним и ничего не списывается.",
  "Waiting on {storeName} to approve the purchase.": "Ждём, пока {storeName} подтвердит покупку.",
  "The purchase didn’t go through. You weren’t charged.": "Покупка не прошла. Деньги не списаны.",
