  "Deleting removes the ride, its chat and its route for everyone.": "Удаление убирает поездку, её чат и маршрут для всех.",
  "Everyone who joined gets a notification and an email either way. Cancel keeps the ride in their list; delete removes it.": "Все, кто присоединился, в любом случае получат уведомление и письмо. Отмена оставляет поездку в их списке; удаление убирает её.",
