  "Build the Route": "Построить маршрут",
  "Mark where the group will stop for fuel, lunch or camp. Every rider sees them numbered on the map, in order.": "Отметьте, где группа остановится на заправку, обед или ночёвку. Каждый райдер видит их на карте пронумерованными по порядку.",
  "Mark camp, fuel, a viewpoint or a hazard. Share each one with the whole ride, or keep it to yourself.": "Отметьте лагерь, заправку, смотровую площадку или опасность. Поделитесь каждой точкой со всей поездкой или оставьте себе.",
