  "Imported{v}. Clear it to draw your own.": "Импортировано{v}. Очистите, чтобы нарисовать свою.",
  "{v} the map where the ride starts, or Search for the trailhead.": "{v} карту там, где начинается поездка, или найдите начало трассы.",
  "No mapped trail joins those points, so that part is a straight line. Add a point on the trail or zoom in.": "Ни одна нанесённая трасса не соединяет эти точки, поэтому этот участок — прямая линия. Добавьте точку на трассе или приблизьте карту.",
  "Now {click} further along the trail. The route follows it for you.": "Теперь {click} дальше по трассе. Маршрут проследует по ней за вас.",
