  "Keep {v} along the trail. Drag a point to move it{v2}.": "Продолжайте {v} вдоль трассы. Перетащите точку, чтобы переместить её{v2}.",
  "Straight lines between points. Switch to Follow Trails to snap to the trail.": "Прямые линии между точками. Переключитесь на «По трассам», чтобы привязаться к трассе.",
  "Tap a line to see who can ride it.": "Нажмите на линию, чтобы увидеть, кто может по ней проехать.",
