  "{drop} the map at {name} to drop {v} there.": "{drop} карту у {name}, чтобы поставить там {v}.",
  "{drop} the map where the group will stop, or Search for the place. Stops are numbered in the order you add them.": "{drop} карту там, где группа остановится, или найдите место. Остановки нумеруются в порядке добавления.",
  "{drop} the map to drop a waypoint, or Search for a place. You choose whether the whole ride sees it.": "{drop} карту, чтобы поставить точку маршрута, или найдите место. Вы решаете, увидит ли её вся поездка.",
  "{drop} the map to drop a waypoint, or Search for a place. Yours are only for you.": "{drop} карту, чтобы поставить точку маршрута, или найдите место. Ваши точки только для вас.",
  "Could not copy that ride.": "Не удалось скопировать эту поездку.",
  "Trail width limit: {v}. Wider machines won’t fit.": "Ограничение ширины трассы: {v}. Более широкая техника не пройдёт.",
  "Checking your invite code. Try again in a second.": "Проверяем ваш код приглашения. Попробуйте через секунду.",
