  "Your rides, badges and trails show here. With Pro you can post ride reports and photos too.": "Здесь показываются ваши поездки, значки и трассы. С Pro вы можете публиковать и отчёты о поездках с фото.",
  "It comes off for everyone.": "Исчезает для всех.",
