  "Enter an OnMyLead promo code in Google Play": "Введите промокод OnMyLead в Google Play",
  "Enter an OnMyLead offer code from Apple": "Введите код предложения OnMyLead от Apple",
  "Something not working, or a question about OnMyLead? Send us a message with the Contact Us form below, or email {v}, and a real person at {v2} will answer, usually within a day.": "Что-то не работает или есть вопрос об OnMyLead? Напишите нам через форму «Связаться с нами» ниже или на {v}, и живой человек из {v2} ответит, обычно в течение дня.",
  "Ask the organizer for the ride code or link, or scan their QR code with your {v} camera. Then tap Join a Ride on the Rides tab.": "Попросите у организатора код или ссылку на поездку либо отсканируйте его QR-код камерой {v}. Затем нажмите «Присоединиться к поездке» на вкладке «Поездки».",
  "Refunds are handled by Google Play at play.google.com/store/account/orderhistory.": "Возвратами занимается Google Play на play.google.com/store/account/orderhistory.",
