  "Could not change your machine.": "Не удалось сменить вашу технику.",
  "Your Machine": "Ваша техника",
  "Already have it? Open the ride right where you left off. New here? Get the app, then scan or open the link again.": "Уже есть приложение? Откройте поездку там, где остановились. Впервые здесь? Установите приложение, затем снова отсканируйте или откройте ссылку.",
  "Get the app, then open the link again and the ride opens right in OnMyLead.": "Установите приложение, снова откройте ссылку — и поездка откроется прямо в OnMyLead.",
  "Scan this with your phone’s camera to open the ride on your phone. Your group shares one live map and chat, and the leader’s route.": "Отсканируйте это камерой телефона, чтобы открыть поездку на нём. У вашей группы общая живая карта, чат и маршрут ведущего.",
