  "Invite Riders": "Пригласить райдеров",
  "Only people you send this to can find it. They can scan the QR code, open the link or type the code.": "Найти её смогут только те, кому вы это отправите. Они могут отсканировать QR-код, открыть ссылку или ввести код.",
  "Anyone can find it near them or in your state. Send it to friends too.": "Любой может найти её рядом с собой или в вашем штате. Отправьте её и друзьям.",
  "The old link, QR code and code stop working. Riders already on the ride stay on it.{v}": "Старая ссылка, QR-код и код перестают работать. Райдеры, уже участвующие в поездке, остаются в ней.{v}",
  "Leave Ride. First pick who takes the ride over": "Покинуть поездку. Сначала выберите, кто её возглавит",
