  "Dismiss all {length}": "Закрыть все {length}",
  "Opens Settings. Switch on Notification Access for OnMyLead Music Controls": "Открывает Настройки. Включите доступ к уведомлениям для «OnMyLead: управление музыкой»",
  "Android shares what’s playing only with apps you allow under Notification Access. OnMyLead never reads your notifications.": "Android показывает, что играет, только приложениям, которым вы разрешили в «Доступ к уведомлениям». OnMyLead никогда не читает ваши уведомления.",
  "Lets OnMyLead show the Apple Music song. It stays on your phone.": "Позволяет OnMyLead показывать трек из Apple Music. Остаётся на вашем телефоне.",
  "Search result: {name}": "Результат поиска: {name}",
  "Edit Spot": "Изменить место",
  "Add to Trail": "Добавить к трассе",
  "You’re Out Riding. {v}": "Вы в пути. {v}",
  "Out Riding. See which riders are out near you.": "В пути. Посмотрите, какие райдеры катаются рядом с вами.",
