  "Show {what}": "Показать {what}",
  "Picture": "Фото",
  "Free accounts create {v} a month, and your next one opens on {reset}. Joining other rides stays free.": "Бесплатные аккаунты создают {v} в месяц, следующая откроется {reset}. Присоединяться к чужим поездкам по-прежнему бесплатно.",
  "{v}. Part of OnMyLead Pro": "{v}. Часть OnMyLead Pro",
  "Ends {v}. No payment needed, and you’re never charged when it ends. Your rides, routes, groups and maps stay yours; new Pro actions move to Free unless you subscribe.": "Заканчивается {v}. Платить не нужно, и по окончании деньги не списываются. Ваши поездки, маршруты, группы и карты остаются с вами; новые действия Pro переходят в бесплатный режим, если вы не оформите подписку.",
  "Complimentary Pro until {v}.": "Подарочный Pro до {v}.",
  "Complimentary Pro from OnMyLead.": "Подарочный Pro от OnMyLead.",
  "Renews or ends {v}.{v2} Change it in Manage Subscription.": "Продлевается или заканчивается {v}.{v2} Измените в «Управлять подпиской».",
  "Every Pro feature is on.": "Все функции Pro включены.",
  "{length} riders out within {radius} miles": "{length} райдеров в пути в радиусе {radius} миль",
  "under a mile": "меньше мили",
  "Thanks. Enough riders said this line is off, so it’s now hidden from the public map.": "Спасибо. Достаточно райдеров сообщили, что эта линия неверна, поэтому она скрыта с публичной карты.",
  "Thanks. Your rating helps other riders pick a trail.": "Спасибо. Ваша оценка помогает другим райдерам выбирать трассу.",
  "Couldn’t save your rating. Try again.": "Не удалось сохранить оценку. Попробуйте снова.",
  "You followed {v} of it in Map Mode.": "Вы проехали по ней {v} в режиме карты.",
  "Only rate this if you rode it. Does the line on the map match the trail on the ground?": "Оценивайте, только если проехали по ней. Совпадает ли линия на карте с трассой на местности?",
  "Confirm the code in the App Store. Pro turns on here as soon as Apple confirms it.": "Подтвердите код в App Store. Pro включится здесь, как только Apple его подтвердит.",
  "Open the App Store and redeem code {code}.": "Откройте App Store и активируйте код {code}.",
  "Waiting on Google Play to approve the purchase.": "Ждём, пока Google Play подтвердит покупку.",
  "Google Play didn’t offer the discount on this device. Update OnMyLead from Google Play and try again. You weren’t charged.": "Google Play не предложил скидку на этом устройстве. Обновите OnMyLead из Google Play и попробуйте снова. Деньги не списаны.",
  "Done. Your next Google Play bill moved back 6 months, to {date}.": "Готово. Ваш следующий платёж в Google Play сдвинут на 6 месяцев, на {date}.",
  "Pro creates as many rides as you lead.": "С Pro можно создавать сколько угодно поездок, которые вы ведёте.",
