  'Could not save the ride.': 'Не удалось сохранить выезд.',
  'The Ride Is Live': 'Выезд идёт',
  'The day, times and meeting point stay as they are while everyone is out riding. The name and details below can still change.': 'День, время и точка сбора не меняются, пока все в пути. Название и детали ниже ещё можно изменить.',
  'Listed in {v}': 'В списке: {v}',
  'About the Ride': 'О выезде',
  'Lowering a limit never removes anyone who already joined.': 'Снижение лимита никогда не удаляет тех, кто уже присоединился.',
  'Bring and Know': 'Взять с собой и знать',
  'Not Ready to Save': 'Пока нельзя сохранить',
  'No Changes Yet': 'Пока без изменений',
